import React, { useState } from 'react';
import api from '../api';

function TaskItem({ task, onUpdate }) {
  const [showDetails, setShowDetails] = useState(false);
  const [comment, setComment] = useState('');
  const [uploading, setUploading] = useState(false);

  const hasSubtasks = task.subtasks && task.subtasks.length > 0;
  const isCompleted = hasSubtasks 
    ? task.subtasks.every(st => st.is_completed === 1)
    : !!task.completion_id;

  const handleToggle = async () => {
    if (hasSubtasks) {
      // Don't allow manual toggle if task has subtasks
      return;
    }

    try {
      if (isCompleted) {
        await api.uncompleteTask(task.id);
      } else {
        await api.completeTask(task.id);
      }
      onUpdate();
    } catch (error) {
      console.error('Error toggling task:', error);
    }
  };

  const handleSubtaskToggle = async (subtask) => {
    try {
      if (subtask.is_completed) {
        await api.uncompleteSubtask(task.id, subtask.id);
      } else {
        await api.completeSubtask(task.id, subtask.id);
      }
      onUpdate();
    } catch (error) {
      console.error('Error toggling subtask:', error);
    }
  };

  const handleAddComment = async (e) => {
    e.preventDefault();
    if (!comment.trim()) return;

    try {
      await api.addComment(task.id, comment);
      setComment('');
      onUpdate();
    } catch (error) {
      console.error('Error adding comment:', error);
    }
  };

  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setUploading(true);
    try {
      await api.uploadFile(task.id, file);
      onUpdate();
    } catch (error) {
      console.error('Error uploading file:', error);
    } finally {
      setUploading(false);
      e.target.value = '';
    }
  };

  return (
    <div className={`task-item ${isCompleted ? 'completed' : ''}`}>
      <div className="task-header">
        <input
          type="checkbox"
          className="task-checkbox"
          checked={isCompleted}
          onChange={handleToggle}
          disabled={hasSubtasks}
          style={{ cursor: hasSubtasks ? 'not-allowed' : 'pointer' }}
        />
        <div className="task-content">
          <div className="task-title">{task.title}</div>
          {task.description && (
            <div className="task-description">{task.description}</div>
          )}

          {/* Subtasks */}
          {hasSubtasks && (
            <div style={{ marginTop: '15px', marginLeft: '20px' }}>
              {task.subtasks.map((subtask) => (
                <div key={subtask.id} style={{ 
                  display: 'flex', 
                  alignItems: 'center', 
                  gap: '10px', 
                  marginBottom: '8px',
                  padding: '8px',
                  backgroundColor: subtask.is_completed ? '#f8f9fa' : 'transparent',
                  borderRadius: '4px'
                }}>
                  <input
                    type="checkbox"
                    checked={subtask.is_completed === 1}
                    onChange={() => handleSubtaskToggle(subtask)}
                    style={{ cursor: 'pointer' }}
                  />
                  <span style={{ 
                    textDecoration: subtask.is_completed ? 'line-through' : 'none',
                    color: subtask.is_completed ? '#7f8c8d' : '#2c3e50'
                  }}>
                    {subtask.name}
                  </span>
                </div>
              ))}
            </div>
          )}

          <div className="task-actions" style={{ marginTop: '10px' }}>
            <button
              className="btn btn-secondary"
              onClick={() => setShowDetails(!showDetails)}
            >
              {showDetails ? 'Hide Details' : 'Show Details'}
            </button>
            <label className="btn btn-primary">
              {uploading ? 'Uploading...' : '📎 Upload File'}
              <input
                type="file"
                style={{ display: 'none' }}
                onChange={handleFileUpload}
                disabled={uploading}
              />
            </label>
          </div>
        </div>
      </div>

      {showDetails && (
        <div className="task-details">
          {/* Completion Status */}
          {task.completions && task.completions.length > 0 && (
            <div style={{ marginBottom: '20px' }}>
              <strong>✓ Completed by:</strong>
              <div style={{ marginTop: '10px' }}>
                {task.completions.map((completion) => (
                  <div key={completion.id} style={{ 
                    padding: '8px 12px',
                    backgroundColor: '#e8f5e9',
                    borderLeft: '3px solid #4caf50',
                    marginBottom: '8px',
                    borderRadius: '4px'
                  }}>
                    <div style={{ fontWeight: '600', color: '#2c3e50' }}>
                      {completion.user_name}
                    </div>
                    <div style={{ fontSize: '12px', color: '#7f8c8d', marginTop: '4px' }}>
                      {new Date(completion.completed_at).toLocaleString('en-US')}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Files */}
          {task.files && task.files.length > 0 && (
            <div className="file-list">
              <strong>Files:</strong>
              {task.files.map((file) => (
                <div key={file.id} className="file-item">
                  <span className="file-icon">📄</span>
                  <div className="file-info">
                    <div className="file-name">
                      <a href={`/uploads/${file.filename}`} target="_blank" rel="noopener noreferrer">
                        {file.original_name}
                      </a>
                    </div>
                    <div className="file-meta">
                      Uploaded by {file.user_name} on {new Date(file.uploaded_at).toLocaleString('en-US')}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Comments */}
          <div className="comment-form">
            <form onSubmit={handleAddComment}>
              <div className="form-group">
                <label>Add Comment</label>
                <textarea
                  className="form-control"
                  value={comment}
                  onChange={(e) => setComment(e.target.value)}
                  placeholder="Type your comment here..."
                />
              </div>
              <button type="submit" className="btn btn-success">
                Post Comment
              </button>
            </form>
          </div>

          {task.comments && task.comments.length > 0 && (
            <div className="comment-list">
              <strong>Comments:</strong>
              {task.comments.map((c) => (
                <div key={c.id} className="comment-item">
                  <div className="comment-header">
                    <span className="comment-author">{c.user_name}</span>
                    <span>{new Date(c.created_at).toLocaleString('en-US')}</span>
                  </div>
                  <div className="comment-text">{c.comment}</div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default TaskItem;
